    [Fact]
    public async Task Customer_CanDiscoverCreateListAndReadOwnProject_WhileRolesAndOtherCustomerAreProtected()
    {
        var request=await SeedRequest();using var anonymous=Client();var services=await anonymous.GetFromJsonAsync<List<InteriorServiceResponse>>("/api/v1/public/interior/services");Assert.Contains(services!,x=>x.Id==factory.Catalog.ServiceId);
        using var customer=Client();using var other=Client();using var provider=Client();await Login(customer,factory.Credentials[RoleCodes.Customer]);await Login(other,factory.OtherCustomerCredential);await Login(provider,factory.Credentials[RoleCodes.Provider]);
        var create=await customer.PostAsJsonAsync("/api/v1/customers/me/interior/projects",new{serviceRequestId=request,idempotencyKey=$"customer-project-{Guid.NewGuid():N}"});Assert.Equal(HttpStatusCode.OK,create.StatusCode);var project=(await create.Content.ReadFromJsonAsync<CustomerInteriorProjectDetail>())!;Assert.Equal("CONSULTATION",project.StatusCode);Assert.NotNull(project.RowVersion);Assert.DoesNotContain("feeAssessment",await create.Content.ReadAsStringAsync(),StringComparison.OrdinalIgnoreCase);
        Assert.Contains((await customer.GetFromJsonAsync<List<ServiceRequestListItemResponse>>("/api/v1/requests"))!,x=>x.Id==request&&x.Domain=="INTERIOR");
        Assert.Contains((await customer.GetFromJsonAsync<List<CustomerInteriorProjectListItem>>("/api/v1/customers/me/interior/projects"))!,x=>x.Id==project.Id);Assert.Equal(HttpStatusCode.NotFound,(await other.GetAsync($"/api/v1/customers/me/interior/projects/{project.Id}")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await provider.GetAsync("/api/v1/customers/me/interior/projects")).StatusCode);
    }

    [Fact]
    public async Task SiteVisitSelection_PreservesPreselectionPrivacy_AndCustomerReadsActualMeasurements()
    {
        var flow=await CreateProject();using var admin=flow.Admin;using var customer=flow.Customer;using var provider=Client();using var otherProvider=Client();await Login(provider,factory.Credentials[RoleCodes.Provider]);await Login(otherProvider,factory.AreaMismatchProviderCredential);var providerId=await ProviderId(factory.Credentials[RoleCodes.Provider]);_ = await SeedQuote(flow.RequestId,providerId);
        using(var scope=factory.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<SoodalLifeDbContext>();var request=await db.ServiceRequests.SingleAsync(x=>x.PublicId==flow.RequestId);request.DetailAddress=null;await db.SaveChangesAsync();}
        var add=await provider.PostAsJsonAsync($"/api/v1/providers/me/interior/projects/{flow.Project.Id}/site-visit-proposals",new{scheduledStartAt=DateTime.UtcNow.AddDays(1),scheduledEndAt=DateTime.UtcNow.AddDays(1).AddHours(2),proposedVisitFee=0m,proposalTerms="공동현관 호출",idempotencyKey=$"visit-{Guid.NewGuid():N}"});Assert.Equal(HttpStatusCode.OK,add.StatusCode);var proposed=await customer.GetFromJsonAsync<CustomerInteriorProjectDetail>($"/api/v1/customers/me/interior/projects/{flow.Project.Id}");var visit=Assert.Single(proposed!.SiteVisits);
        Assert.Equal(HttpStatusCode.NotFound,(await provider.GetAsync($"/api/v1/interior/site-visits/{visit.Id}")).StatusCode);var detail=await customer.GetFromJsonAsync<CustomerInteriorProjectDetail>($"/api/v1/customers/me/interior/projects/{flow.Project.Id}");Assert.True(Assert.Single(detail!.SiteVisits).CanSelect);
        Assert.Equal(HttpStatusCode.BadRequest,(await customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/site-visits/{visit.Id}/selection",new{detailAddress="",idempotencyKey=$"empty-{Guid.NewGuid():N}"})).StatusCode);
        Assert.Equal(HttpStatusCode.OK,(await customer.PostAsJsonAsync($"/api/v1/customers/me/interior/projects/{flow.Project.Id}/site-visits/{visit.Id}/selection",new{detailAddress="효동로 72-1, 3층 301호",idempotencyKey=$"select-{Guid.NewGuid():N}"})).StatusCode);var privateView=await provider.GetFromJsonAsync<ProviderSiteVisitPrivateResponse>($"/api/v1/interior/site-visits/{visit.Id}");Assert.Equal("효동로 72-1, 3층 301호",privateView!.DetailAddress);Assert.Equal(HttpStatusCode.OK,(await provider.GetAsync($"/api/v1/providers/me/interior/projects/{flow.Project.Id}")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await otherProvider.GetAsync($"/api/v1/interior/site-visits/{visit.Id}")).StatusCode);
        var providerDetail=await provider.GetFromJsonAsync<ProviderInteriorDetail>($"/api/v1/providers/me/interior/projects/{flow.Project.Id}");var providerVisit=Assert.Single(providerDetail!.SiteVisits,x=>x.Id==visit.Id);var complete=await provider.PostAsJsonAsync($"/api/v1/providers/me/interior/site-visits/{visit.Id}/completion",new{measurementSummary="주방 실측 완료",constraint="엘리베이터 시간 제한",riskNote="가스 배관 확인",measurements=new[]{new{key="kitchen_width",value=3.4m,text=(string?)null,unit="m",location="주방",note="마감 전 기준",additionalDataJson=(string?)null}},fileIds=Array.Empty<Guid>(),idempotencyKey=$"measure-{Guid.NewGuid():N}",rowVersion=providerVisit.RowVersion});Assert.Equal(HttpStatusCode.OK,complete.StatusCode);
        detail=await customer.GetFromJsonAsync<CustomerInteriorProjectDetail>($"/api/v1/customers/me/interior/projects/{flow.Project.Id}");var measured=Assert.Single(detail!.SiteVisits);Assert.Equal("주방 실측 완료",measured.MeasurementSummary);Assert.Equal(3.4m,Assert.Single(measured.Measurements).Value);Assert.Equal("가스 배관 확인",measured.RiskNote);
    }

