        var stageResponse=await provider.PostAsJsonAsync($"/api/v1/providers/me/interior/projects/{flow.Project.Id}/stages",new{sequenceNo=1,name="철거",plannedStartDate=DateOnly.FromDateTime(DateTime.Today.AddDays(3)),plannedEndDate=DateOnly.FromDateTime(DateTime.Today.AddDays(6)),idempotencyKey=$"stage-{Guid.NewGuid():N}"});Assert.Equal(HttpStatusCode.OK,stageResponse.StatusCode);var stage=Assert.Single((await stageResponse.Content.ReadFromJsonAsync<ProviderInteriorDetail>())!.Stages);
        await provider.PostAsJsonAsync($"/api/v1/interior/stages/{stage.Id}/updates",new{progressPercent=60,updateText="철거 진행",issueText="폐기물 반출 일정 확인",fileIds=Array.Empty<Guid>(),idempotencyKey=$"update-{Guid.NewGuid():N}",rowVersion=(string?)null});var correction=await provider.PostAsJsonAsync($"/api/v1/providers/me/interior/stages/{stage.Id}/inspections",new{statusCode="CORRECTION_REQUIRED",checklistJson="{\"clean\":false}",result="보완 필요",correction="잔재물 정리",fileIds=Array.Empty<Guid>(),idempotencyKey=$"inspect-{Guid.NewGuid():N}",rowVersion=(string?)null});Assert.Equal(HttpStatusCode.OK,correction.StatusCode);
        var changeResponse=await provider.PostAsJsonAsync($"/api/v1/interior/contracts/{contract.Id}/changes",new{changeTypeCode="ADDITIONAL_WORK",reason="고객 요청",scopeChange="수납장 추가",amountDelta=500000m,scheduleImpactDays=2,idempotencyKey=$"change-{Guid.NewGuid():N}"});var change=(await changeResponse.Content.ReadFromJsonAsync<InteriorChangeResponse>())!;
